/* Client-side filter for the "All competencies" table.
 *
 * Wrapped in Material's `document$` observable rather than a DOMContentLoaded listener,
 * because instant navigation swaps page content without a document load — see
 * https://squidfunk.github.io/mkdocs-material/customization/#additional-javascript
 *
 * The markup this drives is generated by scripts/gen_site.py: a `[data-cx-filter]` bar
 * holding a search input and a category select, and a `.cx-table` whose rows carry
 * `data-name` (lower-cased competency name) and `data-category`.
 */
document$.subscribe(function () {
  var bar = document.querySelector("[data-cx-filter]");
  var table = document.querySelector(".cx-table");
  if (!bar || !table) return;

  var query = bar.querySelector(".cx-filter__q");
  var category = bar.querySelector(".cx-filter__cat");
  var count = bar.querySelector(".cx-filter__count");
  var empty = document.querySelector(".cx-filter__empty");
  var rows = Array.prototype.slice.call(table.querySelectorAll("tbody tr"));

  function apply() {
    var q = query.value.trim().toLowerCase();
    var cat = category.value;
    var shown = 0;

    rows.forEach(function (row) {
      var match =
        (!q || row.getAttribute("data-name").indexOf(q) !== -1) &&
        (!cat || row.getAttribute("data-category") === cat);
      row.hidden = !match;
      if (match) shown++;
    });

    count.textContent =
      shown === rows.length
        ? rows.length + " competencies"
        : shown + " of " + rows.length + " shown";
    if (empty) empty.hidden = shown !== 0;
    table.hidden = shown === 0;
  }

  query.addEventListener("input", apply);
  category.addEventListener("change", apply);
  apply();
});
